   119→function AnimatedBackground() {
   120→  const canvasRef = useRef<HTMLCanvasElement>(null);
   121→  useEffect(() => {
   122→    const canvas = canvasRef.current; if (!canvas) return;
   123→    const ctx = canvas.getContext("2d"); if (!ctx) return;
   124→    let raf: number;
   125→    const resize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
   126→    resize(); window.addEventListener("resize", resize);
   127→    const TYPES: IconType[] = ["truck","cart","box","store"];
   128→    const icons = Array.from({ length: 20 }, (_,i) => ({
   129→      x: Math.random()*window.innerWidth, y: Math.random()*window.innerHeight,
   130→      vx: (Math.random()-.5)*.3, vy: (Math.random()-.5)*.3,
   131→      size: 16+Math.random()*14, type: TYPES[i%4],
   132→      pulse: Math.random()*Math.PI*2, pulseSpeed: .015+Math.random()*.02, baseAlpha: .4+Math.random()*.28,
   133→    }));
   134→    const orbs = [
   135→      { x:window.innerWidth*.18, y:window.innerHeight*.28, vx:.14, vy:.09, r:300 },
   136→      { x:window.innerWidth*.82, y:window.innerHeight*.72, vx:-.11, vy:-.08, r:240 },
   137→      { x:window.innerWidth*.55, y:window.innerHeight*.05, vx:.07, vy:.16, r:200 },
   138→    ];
   139→    let tick = 0;
   140→    const draw = () => {
   141→      const W = canvas.width, H = canvas.height;
   142→      ctx.fillStyle = "#020C1C"; ctx.fillRect(0,0,W,H);
   143→      const z1 = ctx.createRadialGradient(W*.22,H*.5,0,W*.22,H*.5,W*.48);
   144→      z1.addColorStop(0,"rgba(29,78,216,.38)"); z1.addColorStop(.4,"rgba(37,99,235,.18)"); z1.addColorStop(1,"rgba(10,30,80,0)");
   145→      ctx.fillStyle=z1; ctx.fillRect(0,0,W,H);
   146→      const z2 = ctx.createRadialGradient(W*.92,H*.08,0,W*.92,H*.08,W*.38);
   147→      z2.addColorStop(0,"rgba(6,182,212,.22)"); z2.addColorStop(.5,"rgba(14,116,144,.10)"); z2.addColorStop(1,"rgba(0,0,0,0)");
   148→      ctx.fillStyle=z2; ctx.fillRect(0,0,W,H);
   149→      const p4 = .09+.04*Math.sin(tick*.009+1.2);
   150→      const z4 = ctx.createRadialGradient(W*.5,H*.5,0,W*.5,H*.5,W*.55);
   151→      z4.addColorStop(0,`rgba(59,130,246,${p4})`); z4.addColorStop(.6,`rgba(37,99,235,${p4*.3})`); z4.addColorStop(1,"rgba(0,0,0,0)");
   152→      ctx.fillStyle=z4; ctx.fillRect(0,0,W,H);
   153→      for(const orb of orbs){
   154→        orb.x+=orb.vx; orb.y+=orb.vy;
   155→        if(orb.x<-orb.r||orb.x>W+orb.r) orb.vx*=-1;
   156→        if(orb.y<-orb.r||orb.y>H+orb.r) orb.vy*=-1;
   157→        const g=ctx.createRadialGradient(orb.x,orb.y,0,orb.x,orb.y,orb.r);
   158→        g.addColorStop(0,"rgba(99,179,255,.22)"); g.addColorStop(.45,"rgba(59,130,246,.10)"); g.addColorStop(1,"rgba(29,78,216,0)");
   159→        ctx.fillStyle=g; ctx.beginPath(); ctx.arc(orb.x,orb.y,orb.r,0,Math.PI*2); ctx.fill();
   160→      }
   161→      ctx.textAlign="center"; ctx.textBaseline="middle";
   162→      [{x:.18,y:.22,s:80,ph:0},{x:.78,y:.72,s:56,ph:1.8},{x:.5,y:.92,s:44,ph:3.4}].forEach(wm=>{
   163→        const a=.18+.06*Math.sin(tick*.007+wm.ph);
   164→        ctx.font=`bold ${wm.s}px system-ui`; ctx.fillStyle=`rgba(147,197,253,${a})`;
   165→        ctx.fillText("LinQi",W*wm.x,H*wm.y);
   166→      });
   167→      for(const ic of icons){
   168→        ic.x+=ic.vx; ic.y+=ic.vy; ic.pulse+=ic.pulseSpeed;
   169→        if(ic.x<-ic.size) ic.x=W+ic.size; if(ic.x>W+ic.size) ic.x=-ic.size;
   170→        if(ic.y<-ic.size) ic.y=H+ic.size; if(ic.y>H+ic.size) ic.y=-ic.size;
   171→      }
   172→      const MAX=160;
   173→      for(let i=0;i<icons.length;i++) for(let j=i+1;j<icons.length;j++){
   174→        const dx=icons[i].x-icons[j].x,dy=icons[i].y-icons[j].y,d2=dx*dx+dy*dy;
   175→        if(d2<MAX*MAX){const d=Math.sqrt(d2);
   176→          ctx.strokeStyle=`rgba(96,165,250,${(1-d/MAX)*.45})`; ctx.lineWidth=.9;
   177→          ctx.beginPath(); ctx.moveTo(icons[i].x,icons[i].y); ctx.lineTo(icons[j].x,icons[j].y); ctx.stroke();}
   178→      }
   179→      for(const ic of icons) drawIcon(ctx,ic.type,ic.x,ic.y,ic.size,ic.baseAlpha+.08*Math.sin(ic.pulse));
   180→      tick++; raf=requestAnimationFrame(draw);
   181→    };
   182→    draw();
   183→    return ()=>{ cancelAnimationFrame(raf); window.removeEventListener("resize",resize); };
   184→  },[]);
   185→  return <canvas ref={canvasRef} className="fixed inset-0 w-full h-full" style={{zIndex:0}} />;
   186→}
