   326→/* ─── GPS Address Field ────────────────────────────────────────────── */
   327→function GpsAddressField({ label, value, onChange }: { label: string; value: string; onChange: (v: string) => void }) {
   328→  const { t } = useTranslation();
   329→  const [loading, setLoading] = useState(false);
   330→  const [ok, setOk] = useState(false);
   331→  const [err, setErr] = useState("");
   332→
   333→  const fetchGPS = () => {
   334→    if (!navigator.geolocation) { setErr(t("onboard.gpsUnsupported")); return; }
   335→    setLoading(true); setErr(""); setOk(false);
   336→    navigator.geolocation.getCurrentPosition(
   337→      async pos => {
   338→        const { latitude: lat, longitude: lng } = pos.coords;
   339→        try {
   340→          const res = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`);
