import { useGetDashboard, useGetProducts } from "@workspace/api-client-react";
import { formatCurrency, formatDate } from "@/lib/utils";
import {
  TrendingUp, TrendingDown, Users, Package,
  ArrowUpRight, ArrowDownRight, CreditCard, Activity, AlertTriangle, PackageOpen,
  Truck, Share2, UtensilsCrossed, Building2, HeartPulse, ShoppingCart,
  Factory, Layers, Briefcase, ShoppingBag, Pill, CheckCircle2, X,
} from "lucide-react";
import {
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
} from "recharts";
import { motion, AnimatePresence } from "framer-motion";
import SalesPredictor from "@/components/SalesPredictor";
import AIInsightsCard from "@/components/AIInsightsCard";
import { useTranslation } from "react-i18next";
import { useAuth } from "@/contexts/AuthContext";
import { useState } from "react";

const LOW_STOCK_THRESHOLD = 5;

/* ── Design tokens ─────────────────────────────────────────────────── */
const D = {
  bg:       "#0d1117",
  card:     "rgba(255,255,255,0.05)",
  cardBorder:"rgba(255,255,255,0.10)",
  glass:    "rgba(255,255,255,0.04)",
  glassBorder:"rgba(255,255,255,0.08)",
  muted:    "#64748B",
  sub:      "#94A3B8",
  text:     "#F1F5F9",
  orange:   "#FF6B00",
  green:    "#10B981",
  red:      "#EF4444",
  blue:     "#3B82F6",
  grid:     "rgba(255,255,255,0.06)",
} as const;

const glassCard: React.CSSProperties = {
  background: D.card,
  border: `1px solid ${D.cardBorder}`,
  backdropFilter: "blur(20px)",
  WebkitBackdropFilter: "blur(20px)",
  borderRadius: "1.25rem",
};

const SECTOR_META: Record<string, { icon: any; color: string; ku: string }> = {
  distributor:  { icon: Share2,          color: "#F59E0B", ku: "دابەشکار" },
  manufacturer: { icon: Factory,         color: "#EF4444", ku: "کارخانە" },
  hospital:     { icon: HeartPulse,      color: "#EC4899", ku: "نەخۆشخانە / کلینیک" },
  supermarket:  { icon: ShoppingBag,     color: "#8B5CF6", ku: "مارکێت" },
  retail_shop:  { icon: ShoppingCart,    color: "#A855F7", ku: "دوکانی تاکەکەسی" },
  restaurant:   { icon: UtensilsCrossed, color: "#F97316", ku: "چێشتخانە" },
  hotel:        { icon: Building2,       color: "#06B6D4", ku: "هۆتێل" },
  pharmacy:     { icon: Pill,            color: "#22C55E", ku: "دەرمانسازی" },
  delivery:     { icon: Truck,           color: "#10B981", ku: "گەیاندن" },
  office:       { icon: Briefcase,       color: "#3B82F6", ku: "نووسینگە" },
  other:        { icon: Layers,          color: "#6B7280", ku: "بزنسی تر" },
};

function SectorWelcomeBanner({ name, sectorKey }: { name: string; sectorKey: string }) {
  const [dismissed, setDismissed] = useState(false);
  const meta = SECTOR_META[sectorKey] ?? SECTOR_META.other;
  const SectorIcon = meta.icon;
  if (dismissed) return null;
  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0, y: -16, scale: 0.97 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, height: 0 }}
        transition={{ type: "spring", stiffness: 260, damping: 22 }}
        className="rounded-2xl p-4 flex items-center gap-4 relative overflow-hidden"
        style={{
          background: `linear-gradient(135deg, ${meta.color}18 0%, ${meta.color}08 100%)`,
          border: `1px solid ${meta.color}35`,
        }}
      >
        <div className="w-12 h-12 rounded-2xl flex items-center justify-center flex-shrink-0"
          style={{ background: `${meta.color}22`, border: `1.5px solid ${meta.color}45` }}>
          <SectorIcon className="w-6 h-6" style={{ color: meta.color }} />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-0.5">
            <CheckCircle2 className="w-3.5 h-3.5 flex-shrink-0" style={{ color: D.green }} />
            <span className="text-xs font-bold" style={{ color: D.green }}>ئەکاونتت چالاک بوو</span>
          </div>
          <p className="text-sm font-bold truncate" style={{ color: D.text }}>
            بەخێربێیت، <span style={{ color: meta.color }}>{name}</span>!
          </p>
          <p className="text-xs" style={{ color: D.sub }}>بزنسەکەت وەک <strong style={{ color: D.text }}>{meta.ku}</strong> تۆمارکراوە</p>
        </div>
        <button onClick={() => setDismissed(true)}
          className="flex-shrink-0 w-7 h-7 rounded-lg flex items-center justify-center transition-colors"
          style={{ color: D.muted, background: "rgba(255,255,255,0.06)" }}>
          <X className="w-4 h-4" />
        </button>
      </motion.div>
    </AnimatePresence>
  );
}

/* ── Custom Recharts Tooltip ─────────────────────────────────────── */
function ChartTooltip({ active, payload, label }: any) {
  if (!active || !payload?.length) return null;
  return (
    <div style={{
      background: "rgba(13,17,23,0.95)",
      border: "1px solid rgba(255,255,255,0.15)",
      borderRadius: "0.75rem",
      padding: "10px 14px",
      backdropFilter: "blur(12px)",
      boxShadow: "0 8px 32px rgba(0,0,0,0.6)",
    }}>
      <p style={{ color: D.sub, fontSize: "11px", marginBottom: "4px" }}>{label}</p>
      <p style={{ color: "#60A5FA", fontWeight: 700, fontSize: "14px" }}>
        {new Intl.NumberFormat("ku-IQ").format(payload[0].value)} د.ع
      </p>
    </div>
  );
}

export default function Dashboard() {
  const { t } = useTranslation();
  const { user } = useAuth();
  const { data: stats, isLoading, error } = useGetDashboard();
  const { data: products = [] } = useGetProducts();
  const lowStockProducts = products.filter((p) => p.stock < LOW_STOCK_THRESHOLD);

  const sectorKey: string = (user as any)?.sectorKey ?? localStorage.getItem("linqi_sector") ?? "";

  if (isLoading) {
    return (
      <div className="h-full flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (error || !stats) {
    return (
      <div className="p-8 text-center rounded-2xl" style={{ background: "rgba(239,68,68,0.1)", border: "1px solid rgba(239,68,68,0.3)", color: "#FCA5A5" }}>
        {t("dashboard.errorLoading")}
      </div>
    );
  }

  const chartData = stats.recentSales
    .slice()
    .reverse()
    .map((sale) => ({
      name: new Date(sale.createdAt).toLocaleDateString(undefined, { day: "numeric", month: "short" }),
      total: sale.totalAmount,
    }));

  const statCards = [
    {
      title: t("dashboard.totalSales"),
      value: formatCurrency(stats.totalSales),
      icon: TrendingUp,
      trend: "up" as const,
      trendValue: "+12.5%",
      accent: "#3B82F6",
      delay: 0,
    },
    {
      title: t("dashboard.totalDebts"),
      value: formatCurrency(stats.totalDebts),
      icon: TrendingDown,
      trend: "down" as const,
      trendValue: "-2.4%",
      accent: "#EF4444",
      delay: 0.08,
    },
    {
      title: t("dashboard.totalCustomers"),
      value: stats.totalCustomers.toString(),
      icon: Users,
      trend: null,
      trendValue: "",
      accent: "#10B981",
      delay: 0.16,
    },
    {
      title: t("dashboard.totalProducts"),
      value: stats.totalProducts.toString(),
      icon: Package,
      trend: null,
      trendValue: "",
      accent: "#8B5CF6",
      delay: 0.24,
      badge: lowStockProducts.length > 0 ? lowStockProducts.length : undefined,
    },
  ];

  return (
    <div className="space-y-7 pb-10">
      {sectorKey && user?.name && (
        <SectorWelcomeBanner name={user.name} sectorKey={sectorKey} />
      )}

      {/* Page heading */}
      <div>
        <h1 className="text-2xl font-extrabold tracking-tight" style={{ color: D.text }}>
          {t("dashboard.title")}
        </h1>
        <p className="text-sm mt-1" style={{ color: D.muted }}>{t("dashboard.subtitle")}</p>
      </div>

      {/* ── Stat Cards ─────────────────────────────────────────────── */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-5">
        {statCards.map((card) => {
          const Icon = card.icon;
          return (
            <motion.div
              key={card.title}
              initial={{ opacity: 0, y: 24 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: card.delay, duration: 0.38 }}
              className="relative overflow-hidden p-5 group hover:-translate-y-0.5 transition-transform duration-300"
              style={glassCard}
            >
              {/* Accent glow */}
              <div className="absolute -top-8 -end-8 w-24 h-24 rounded-full opacity-20 group-hover:opacity-30 transition-opacity duration-500"
                style={{ background: `radial-gradient(circle, ${card.accent}, transparent 70%)` }} />

              <div className="flex justify-between items-start relative z-10">
                <div className="flex-1 min-w-0">
                  <p className="text-xs font-semibold uppercase tracking-wide mb-2" style={{ color: D.muted }}>
                    {card.title}
                  </p>
                  <h3 className="text-2xl font-extrabold leading-none" style={{ color: D.text }}>
                    {card.value}
                  </h3>
                </div>
                <div className="relative">
                  <div className="w-12 h-12 rounded-2xl flex items-center justify-center flex-shrink-0"
                    style={{ background: `${card.accent}22`, border: `1.5px solid ${card.accent}45` }}>
                    <Icon className="w-5 h-5" style={{ color: card.accent }} />
                  </div>
                  {card.badge !== undefined && (
                    <span className="absolute -top-2 -start-2 w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-black text-white animate-pulse"
                      style={{ background: D.red, boxShadow: `0 0 10px ${D.red}80` }}>
                      {card.badge}
                    </span>
                  )}
                </div>
              </div>

              {card.trend && (
                <div className="mt-4 flex items-center gap-1.5 text-xs font-bold">
                  {card.trend === "up" ? (
                    <>
                      <ArrowUpRight className="w-3.5 h-3.5" style={{ color: D.green }} />
                      <span style={{ color: D.green }}>{card.trendValue}</span>
                    </>
                  ) : (
                    <>
                      <ArrowDownRight className="w-3.5 h-3.5" style={{ color: D.orange }} />
                      <span style={{ color: D.orange }}>{card.trendValue}</span>
                    </>
                  )}
                  <span style={{ color: D.muted, fontWeight: 400 }}>{t("dashboard.fromLastMonth")}</span>
                </div>
              )}
              {lowStockProducts.length > 0 && card.icon === Package && (
                <div className="mt-4 flex items-center gap-1.5 text-xs font-bold">
                  <AlertTriangle className="w-3.5 h-3.5" style={{ color: D.orange }} />
                  <span style={{ color: D.orange }}>
                    {t("dashboard.lowStockItems", { count: lowStockProducts.length })}
                  </span>
                </div>
              )}
            </motion.div>
          );
        })}
      </div>

      {/* ── Sales Predictor ───────────────────────────────────────── */}
      <SalesPredictor />

      {/* ── AI Insights ──────────────────────────────────────────── */}
      <div>
        <div className="flex items-center gap-2 mb-4">
          <span className="text-xl">✨</span>
          <h2 className="text-lg font-extrabold" style={{ color: D.text }}>{t("ai.title")}</h2>
          <span className="text-xs font-bold px-2.5 py-1 rounded-full"
            style={{ background: "rgba(139,92,246,0.2)", color: "#A78BFA", border: "1px solid rgba(139,92,246,0.35)" }}>
            {t("ai.smart")}
          </span>
        </div>
        <AIInsightsCard />
      </div>

      {/* ── Low Stock Alert ───────────────────────────────────────── */}
      {lowStockProducts.length > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4, duration: 0.4 }}
          className="rounded-2xl p-5"
          style={{
            background: "rgba(239,68,68,0.07)",
            border: "1px solid rgba(239,68,68,0.25)",
          }}
        >
          <div className="flex items-center gap-3 mb-4">
            <div className="w-10 h-10 rounded-2xl flex items-center justify-center flex-shrink-0"
              style={{ background: "rgba(239,68,68,0.15)", border: "1px solid rgba(239,68,68,0.3)" }}>
              <AlertTriangle className="w-5 h-5" style={{ color: D.red }} />
            </div>
            <div>
              <h2 className="text-base font-bold" style={{ color: "#FCA5A5" }}>{t("dashboard.lowStockAlert")}</h2>
              <p className="text-xs" style={{ color: "rgba(252,165,165,0.65)" }}>
                {t("dashboard.lowStockDesc", { count: lowStockProducts.length, threshold: LOW_STOCK_THRESHOLD })}
              </p>
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-3">
            {lowStockProducts.map((product) => (
              <div key={product.id}
                className="flex items-center gap-3 p-3 rounded-xl"
                style={{ background: "rgba(239,68,68,0.08)", border: "1px solid rgba(239,68,68,0.18)" }}>
                <div className="w-9 h-9 rounded-lg flex items-center justify-center flex-shrink-0 overflow-hidden"
                  style={{ background: "rgba(239,68,68,0.12)" }}>
                  {product.image ? (
                    <img src={product.image} alt={product.name} className="w-full h-full object-cover" />
                  ) : (
                    <PackageOpen className="w-4 h-4" style={{ color: D.red }} />
                  )}
                </div>
                <div className="min-w-0">
                  <p className="font-bold text-sm truncate" style={{ color: D.text }}>{product.name}</p>
                  <p className="text-xs font-black mt-0.5" style={{ color: product.stock === 0 ? D.muted : D.orange }}>
                    {product.stock === 0
                      ? t("dashboard.outOfStock")
                      : t("dashboard.remaining", { count: product.stock, unit: product.unit })}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </motion.div>
      )}

      {/* ── Chart + Top Debtors ───────────────────────────────────── */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        {/* Chart */}
        <div className="xl:col-span-2 p-6 rounded-2xl" style={glassCard}>
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-base font-bold flex items-center gap-2" style={{ color: D.text }}>
              <Activity className="w-4 h-4" style={{ color: D.blue }} />
              {t("dashboard.salesChart")}
            </h2>
          </div>
          <div className="h-[320px] w-full" dir="ltr">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorTotal" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%"  stopColor="#3B82F6" stopOpacity={0.35} />
                    <stop offset="95%" stopColor="#3B82F6" stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={D.grid} />
                <XAxis
                  dataKey="name"
                  axisLine={false}
                  tickLine={false}
                  tick={{ fill: D.muted, fontSize: 11, fontWeight: 600 }}
                  dy={8}
                />
                <YAxis
                  axisLine={false}
                  tickLine={false}
                  tick={{ fill: D.muted, fontSize: 11, fontWeight: 600 }}
                  dx={-4}
                  tickFormatter={(val) => `${(val / 1000).toFixed(0)}k`}
                  width={36}
                />
                <Tooltip content={<ChartTooltip />} />
                <Area
                  type="monotone"
                  dataKey="total"
                  stroke="#3B82F6"
                  strokeWidth={2.5}
                  fillOpacity={1}
                  fill="url(#colorTotal)"
                  activeDot={{ r: 5, strokeWidth: 0, fill: "#60A5FA" }}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Top Debtors */}
        <div className="p-6 rounded-2xl flex flex-col" style={glassCard}>
          <div className="flex items-center justify-between mb-5">
            <h2 className="text-base font-bold flex items-center gap-2" style={{ color: D.text }}>
              <CreditCard className="w-4 h-4" style={{ color: D.red }} />
              {t("dashboard.topDebtors")}
            </h2>
          </div>
          <div className="flex-1 space-y-3 overflow-y-auto pe-1">
            {stats.topDebtors.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full py-8">
                <div className="w-14 h-14 rounded-2xl flex items-center justify-center mb-3"
                  style={{ background: "rgba(59,130,246,0.1)", border: "1px solid rgba(59,130,246,0.2)" }}>
                  <CreditCard className="w-7 h-7" style={{ color: "rgba(96,165,250,0.5)" }} />
                </div>
                <p className="text-sm text-center" style={{ color: D.muted }}>{t("dashboard.noDebts")}</p>
              </div>
            ) : (
              stats.topDebtors.slice(0, 5).map((debtor, idx) => (
                <div key={debtor.id}
                  className="flex items-center justify-between p-3 rounded-xl transition-colors"
                  style={{ background: D.glass, border: `1px solid ${D.glassBorder}` }}
                  onMouseEnter={e => (e.currentTarget.style.background = "rgba(255,255,255,0.07)")}
                  onMouseLeave={e => (e.currentTarget.style.background = D.glass)}>
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-full flex items-center justify-center text-sm font-black flex-shrink-0"
                      style={{ background: `rgba(59,130,246,0.18)`, color: "#93C5FD", border: "1px solid rgba(59,130,246,0.3)" }}>
                      {debtor.name.charAt(0)}
                    </div>
                    <div>
                      <p className="font-bold text-sm leading-tight" style={{ color: D.text }}>{debtor.name}</p>
                      <p className="text-xs mt-0.5" style={{ color: D.muted }}>{debtor.phone}</p>
                    </div>
                  </div>
                  <p className="font-extrabold text-sm" style={{ color: D.red }}>{formatCurrency(debtor.totalDebt)}</p>
                </div>
              ))
            )}
          </div>
        </div>
      </div>

      {/* ── Recent Sales Table ─────────────────────────────────────── */}
      <div className="rounded-2xl overflow-hidden" style={glassCard}>
        <div className="px-6 py-4 flex items-center gap-2"
          style={{ borderBottom: `1px solid ${D.cardBorder}` }}>
          <Activity className="w-4 h-4" style={{ color: D.blue }} />
          <h2 className="text-base font-bold" style={{ color: D.text }}>{t("dashboard.recentSales")}</h2>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-right">
            <thead>
              <tr style={{ background: "rgba(255,255,255,0.03)", borderBottom: `1px solid ${D.glassBorder}` }}>
