                  {t("dashboard.receiptNo")}
                </th>
                <th className="px-6 py-3.5 text-xs font-bold uppercase tracking-wider" style={{ color: D.muted }}>
                  {t("dashboard.customer")}
                </th>
                <th className="px-6 py-3.5 text-xs font-bold uppercase tracking-wider" style={{ color: D.muted }}>
                  {t("dashboard.paymentType")}
                </th>
                <th className="px-6 py-3.5 text-xs font-bold uppercase tracking-wider" style={{ color: D.muted }}>
                  {t("dashboard.total")}
                </th>
                <th className="px-6 py-3.5 text-xs font-bold uppercase tracking-wider" style={{ color: D.muted }}>
                  {t("reports.date")}
                </th>
              </tr>
            </thead>
            <tbody>
              {stats.recentSales.slice(0, 5).map((sale, idx) => (
                <tr key={sale.id}
                  style={{ borderBottom: `1px solid ${D.glassBorder}` }}
                  onMouseEnter={e => (e.currentTarget.style.background = "rgba(255,255,255,0.03)")}
                  onMouseLeave={e => (e.currentTarget.style.background = "transparent")}>
                  <td className="px-6 py-4 font-mono text-xs font-bold" style={{ color: D.muted }}>
                    #{sale.id}
                  </td>
                  <td className="px-6 py-4 font-bold" style={{ color: D.text }}>
                    {sale.customerName || t("common.generalCustomer")}
                  </td>
                  <td className="px-6 py-4">
                    <span className="inline-flex items-center px-2.5 py-1 rounded-full text-xs font-bold"
                      style={sale.paymentType === "cash"
                        ? { background: "rgba(16,185,129,0.15)", color: "#34D399", border: "1px solid rgba(16,185,129,0.3)" }
                        : { background: "rgba(239,68,68,0.15)", color: "#FCA5A5", border: "1px solid rgba(239,68,68,0.3)" }}>
                      {sale.paymentType === "cash" ? t("dashboard.cashPayment") : t("dashboard.debtPayment")}
                    </span>
                  </td>
                  <td className="px-6 py-4 font-extrabold" style={{ color: "#60A5FA" }}>
                    {formatCurrency(sale.totalAmount)}
                  </td>
                  <td className="px-6 py-4 text-xs" style={{ color: D.muted }}>
                    {formatDate(sale.createdAt)}
                  </td>
                </tr>
              ))}
              {stats.recentSales.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-10 text-center text-sm" style={{ color: D.muted }}>
                    {t("dashboard.noSales")}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

