/* ─────────────────────────────────────────────────────────────────── */
/*  CUSTOM TOOLTIP                                                      */
/* ─────────────────────────────────────────────────────────────────── */
function ChartTooltip({ active, payload, label }: any) {
  if (!active || !payload?.length) return null;
  return (
    <div style={{
      background: "rgba(11,15,23,0.96)",
      border: "1px solid rgba(6,182,212,0.3)",
      borderRadius: "12px",
      padding: "12px 16px",
      backdropFilter: "blur(12px)",
      boxShadow: "0 8px 32px rgba(0,0,0,0.7)",
    }}>
      <p style={{ color: C.muted, fontSize: "11px", marginBottom: "8px", fontWeight: 600 }}>{label}</p>
      {payload.map((p: any, i: number) => (
        <p key={i} style={{ color: p.color, fontWeight: 700, fontSize: "13px", marginBottom: "2px" }}>
          {p.name}: {new Intl.NumberFormat("ku-IQ").format(p.value)} <span style={{ color: C.muted, fontSize: "11px" }}>د.ع</span>
        </p>
      ))}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────── */
/*  PULSE DOT                                                           */
/* ─────────────────────────────────────────────────────────────────── */
function PulseDot({ color }: { color: string }) {
  return (
    <span className="relative flex h-2.5 w-2.5">
      <span className="animate-ping absolute inline-flex h-full w-full rounded-full opacity-60"
        style={{ background: color }} />
      <span className="relative inline-flex rounded-full h-2.5 w-2.5"
        style={{ background: color }} />
    </span>
  );
}

