                  <p className="text-xs font-extrabold shrink-0" style={{ color: C.red }}>
                    {new Intl.NumberFormat("ku-IQ").format(d.totalDebt)} د.ع
                  </p>
                </div>
              ))}
            </div>
          </motion.div>

          {/* Quick Stats Grid */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.55, duration: 0.4 }}
            className="xl:col-span-2"
            style={{ ...glassCard(), padding: "20px" }}
          >
            <div className="flex items-center gap-2 mb-5">
              <div className="w-8 h-8 rounded-lg flex items-center justify-center"
                style={{ background: "rgba(139,92,246,0.12)", border: "1px solid rgba(139,92,246,0.3)" }}>
                <BarChart3 className="w-4 h-4" style={{ color: C.purple }} />
              </div>
              <div>
                <h2 className="text-sm font-extrabold leading-none" style={{ color: C.text }}>دوایین مامەڵەکان</h2>
                <p className="text-[10px] mt-0.5" style={{ color: C.muted }}>فرۆشە نوێکانی پلاتفۆرم</p>
              </div>
            </div>

            <div className="overflow-hidden rounded-xl" style={{ border: `1px solid ${C.border}` }}>
              <table className="w-full text-xs">
                <thead>
                  <tr style={{ background: "rgba(255,255,255,0.04)", borderBottom: `1px solid ${C.border}` }}>
                    {["#", "کڕیار", "جۆری پارەدان", "کۆی گشتی", "کات"].map(h => (
                      <th key={h} className="px-4 py-3 text-start font-bold uppercase tracking-wide"
                        style={{ color: C.muted, fontSize: "10px" }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {stats.recentSales.slice(0, 6).map((sale, idx) => (
                    <tr key={sale.id}
                      style={{ borderBottom: idx < stats.recentSales.length - 1 ? `1px solid rgba(255,255,255,0.04)` : "none" }}
                      onMouseEnter={e => { (e.currentTarget as HTMLTableRowElement).style.background = "rgba(255,255,255,0.03)"; }}
                      onMouseLeave={e => { (e.currentTarget as HTMLTableRowElement).style.background = "transparent"; }}>
                      <td className="px-4 py-3 font-mono font-bold" style={{ color: C.muted }}>#{sale.id}</td>
                      <td className="px-4 py-3 font-bold" style={{ color: C.text }}>{sale.customerName || "کڕیاری گشتی"}</td>
                      <td className="px-4 py-3">
                        <span className="inline-flex items-center px-2 py-0.5 rounded-md text-[10px] font-bold"
                          style={sale.paymentType === "cash"
                            ? { background: "rgba(16,185,129,0.12)", color: "#34d399", border: "1px solid rgba(16,185,129,0.25)" }
                            : { background: "rgba(234,179,8,0.12)",   color: "#fbbf24", border: "1px solid rgba(234,179,8,0.25)" }}>
                          {sale.paymentType === "cash" ? "نەقد" : "قەرز"}
                        </span>
                      </td>
                      <td className="px-4 py-3 font-extrabold" style={{ color: C.cyan }}>
                        {new Intl.NumberFormat("ku-IQ").format(sale.totalAmount)} <span style={{ color: C.muted, fontWeight: 400 }}>د.ع</span>
                      </td>
                      <td className="px-4 py-3 text-[10px]" style={{ color: C.muted }}>
                        {new Date(sale.createdAt).toLocaleTimeString("ku-IQ", { hour: "2-digit", minute: "2-digit" })}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </motion.div>
        </div>

      </div>
    </div>
  );
}

