const ACTIVITY = [
  { id: "TXN-8841", label: "فرۆشی کۆمارەیی",          customer: "شیرکەتی ئەڵفا",    amount: 4_200_000, status: "جێبەجێکرا", time: "٩:١٤ پ.ن",  type: "sale"      },
  { id: "RFQ-2204", label: "داواکاری نرخی تازە",       customer: "کۆمپانیای بێتا",   amount: 0,         status: "بەرێوەیە",  time: "٨:٥٧ پ.ن",  type: "rfq"       },
