  { id: "TXN-8840", label: "قەبوولکردنی داواکاری",     customer: "گروپی گاما",       amount: 3_200_000, status: "جێبەجێکرا", time: "٨:١٥ پ.ن",  type: "sale"      },
  { id: "RFQ-2203", label: "داواکاری کڕینی کۆمپانیا",  customer: "دەلتا تریدینگ",    amount: 0,         status: "جێبەجێکرا", time: "٧:٤٨ پ.ن",  type: "rfq"       },
  { id: "TXN-8839", label: "فرۆشی دانەبەدانە",         customer: "ئەحمەد کەریم",     amount: 1_850_000, status: "جێبەجێکرا", time: "٧:٢٠ پ.ن",  type: "sale"      },
  { id: "LOG-0316", label: "گواستنەوەی ئەنبار",        customer: "ئەربیل ← سلێمانی", amount: 0,         status: "بەرێوەیە",  time: "دوێنێ",     type: "logistics" },
];

const STATUS_STYLE: Record<string, { bg: string; color: string; border: string }> = {
  "جێبەجێکرا": { bg: "rgba(16,185,129,0.10)", color: "#34d399", border: "rgba(16,185,129,0.22)" },
  "بەرێوەیە":  { bg: "rgba(59,130,246,0.10)",  color: "#60a5fa", border: "rgba(59,130,246,0.22)" },
  "چاوەڕوانە": { bg: "rgba(234,179,8,0.10)",   color: "#fbbf24", border: "rgba(234,179,8,0.22)"  },
};

const TYPE_ICON: Record<string, React.ElementType> = {
  sale:      ShoppingCart,
  rfq:       FileText,
  logistics: Truck,
};

const TYPE_COLOR: Record<string, string> = {
  sale:      C.cyan,
  rfq:       C.purple,
  logistics: C.green,
};

/* ─────────────────────────────────────────────────────────────────── */
/*  SUBCOMPONENTS                                                       */
/* ─────────────────────────────────────────────────────────────────── */
function PulseDot({ color, size = "h-2 w-2" }: { color: string; size?: string }) {
  return (
    <span className={`relative flex ${size}`}>
      <span className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-50`}
        style={{ background: color }} />
      <span className={`relative inline-flex rounded-full h-full w-full`}
        style={{ background: color }} />
    </span>
  );
}

function ChartTooltip({ active, payload, label }: any) {
  if (!active || !payload?.length) return null;
  return (
    <div style={{
      background:    "rgba(11,15,23,0.97)",
      border:        "1px solid rgba(6,182,212,0.25)",
      borderRadius:  "12px",
      padding:       "12px 16px",
      backdropFilter:"blur(16px)",
      boxShadow:     "0 8px 32px rgba(0,0,0,0.75)",
    }}>
      <p style={{ color: C.muted, fontSize: "11px", marginBottom: "8px", fontWeight: 600 }}>{label}</p>
      {payload.map((p: any, i: number) => (
        <div key={i} className="flex items-center gap-2" style={{ marginBottom: "3px" }}>
          <div className="w-2 h-2 rounded-full" style={{ background: p.color, flexShrink: 0 }} />
          <p style={{ color: p.color, fontWeight: 700, fontSize: "13px" }}>
            {p.name}:{" "}
            <span style={{ color: C.text }}>
              {new Intl.NumberFormat("ku-IQ").format(p.value)}
            </span>{" "}
            <span style={{ color: C.muted, fontSize: "11px" }}>د.ع</span>
          </p>
        </div>
      ))}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────── */
/*  MAIN DASHBOARD                                                      */
/* ─────────────────────────────────────────────────────────────────── */
export default function Dashboard() {
  const { user }                         = useAuth();
  const { data: apiStats }               = useGetDashboard();
  const stats                            = apiStats ?? MOCK_STATS;
  const [currency, setCurrency]          = useState<"IQD" | "USD">("IQD");
  const [chartRange, setChartRange]      = useState<"هەفتە" | "مانگ" | "ساڵ">("مانگ");
  const [now]                            = useState(new Date());

  const RATE = 1_310;
  const fmt  = (v: number) =>
    currency === "IQD"
      ? new Intl.NumberFormat("ku-IQ").format(v) + "\u00A0د.ع"
      : "$" + new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(v / RATE);

  const timeStr = now.toLocaleTimeString("ar-IQ", { hour: "2-digit", minute: "2-digit" });
  const dateStr = now.toLocaleDateString("ar-IQ",  { weekday: "long", year: "numeric", month: "long", day: "numeric" });

  const METRIC_CARDS = [
    {
      label:   "کۆیی گشتی فرۆش",
      value:   fmt(stats.totalSales),
      badge:   "+12.4%",
      up:      true,
      sub:     "گەشەی لە مانگی پێشوو",
      icon:    TrendingUp,
      accent:  C.cyan,
    },
    {
      label:   "کۆگا و بریکارە چالاکەکان",
      value:   stats.totalCustomers.toString(),
      badge:   "+8 ئەمسەر",
      up:      true,
      sub:     "کۆمپانیا و بریکارە دابەشکەرەکان",
      icon:    Users,
      accent:  C.purple,
    },
    {
