                      <td className="px-4 py-3" style={{ color: C.muted, fontSize: "10px" }}>
                        {new Date(sale.createdAt).toLocaleTimeString("ar-IQ", { hour: "2-digit", minute: "2-digit" })}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </motion.div>

        </div>
      </div>
    </div>
  );
}

