function pickResponse(input: string): string {
  const q = input.toLowerCase();
  if (q.includes("فرۆش") || q.includes("داهات") || q.includes("sales"))
    return AI_RESPONSES.sales[0];
  if (q.includes("ئەنبار") || q.includes("ستۆک") || q.includes("کاڵا") || q.includes("inventory"))
    return AI_RESPONSES.inventory[0];
  if (q.includes("ستراتیژ") || q.includes("پێشنیار") || q.includes("strategy"))
    return AI_RESPONSES.strategy[0];
  if (q.includes("ڕاپۆرت") || q.includes("report"))
    return AI_RESPONSES.report[0];
  if (q.includes("بازاڕ") || q.includes("market"))
    return AI_RESPONSES.market[0];
  return AI_RESPONSES.default[0];
}

