/* ─────────────────────────────────────────────────────────────────── */
/*  MARKDOWN-LITE RENDERER (bold + line breaks)                        */
/* ─────────────────────────────────────────────────────────────────── */
function MsgText({ text }: { text: string }) {
  const lines = text.split("\n");
  return (
    <div style={{ fontFamily: "Vazirmatn,sans-serif", lineHeight: "1.7", fontSize: "13px" }}>
      {lines.map((line, i) => {
        const parts = line.split(/\*\*(.*?)\*\*/g);
        return (
          <p key={i} style={{ marginBottom: i < lines.length - 1 ? "3px" : 0 }}>
            {parts.map((part, j) =>
              j % 2 === 1
                ? <strong key={j} style={{ color: TEXT, fontWeight: 800 }}>{part}</strong>
                : <span key={j}>{part}</span>
            )}
          </p>
        );
      })}
    </div>
  );
}

