          animate={{ y: [0, -5, 0], opacity: [0.4, 1, 0.4] }}
          transition={{ duration: 0.7, repeat: Infinity, delay: i * 0.15 }}
        />
      ))}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────── */
/*  MAIN PAGE                                                           */
/* ─────────────────────────────────────────────────────────────────── */
export default function AIAssistant() {
  const [messages, setMessages] = useState<Message[]>([
    {
      id:   "welcome",
      role: "assistant",
      text: AI_RESPONSES.default[0],
      ts:   new Date(),
    },
  ]);
  const [input, setInput]       = useState("");
  const [loading, setLoading]   = useState(false);
  const bottomRef               = useRef<HTMLDivElement>(null);
  const inputRef                = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = useCallback(async (text: string) => {
    if (!text.trim() || loading) return;
    const userMsg: Message = { id: Date.now().toString(), role: "user", text: text.trim(), ts: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput("");
    setLoading(true);

    /* Typing placeholder */
    const typingId = `typing-${Date.now()}`;
    setMessages(prev => [...prev, { id: typingId, role: "assistant", text: "", ts: new Date(), typing: true }]);

    /* Simulate latency: 1.2–2.2 s */
    const delay = 1200 + Math.random() * 1000;
    await new Promise(r => setTimeout(r, delay));

    const response = pickResponse(text);
    setMessages(prev =>
      prev.map(m => m.id === typingId
        ? { ...m, text: response, typing: false }
        : m
      )
    );
    setLoading(false);
  }, [loading]);

  const handleKey = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendMessage(input);
    }
  };

  const fmtTime = (d: Date) =>
    d.toLocaleTimeString("ar-IQ", { hour: "2-digit", minute: "2-digit" });

  return (
    <div dir="rtl" style={{ background: BG, minHeight: "100%", display: "flex", flexDirection: "column", gap: "20px" }}>

      {/* ── Header ── */}
      <motion.div
        initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
        className="relative overflow-hidden rounded-2xl p-5"
        style={{
          background: `linear-gradient(135deg, ${PURPLE}18 0%, rgba(8,13,30,0.97) 60%)`,
          border: `1px solid ${PURPLE}30`,
          boxShadow: `0 8px 48px ${PURPLE}14`,
        }}>
        <div style={{
          position: "absolute", top: "-30px", insetInlineEnd: "-20px",
          width: "150px", height: "150px", borderRadius: "50%",
          background: `radial-gradient(circle, ${PURPLE}22, transparent 70%)`,
          filter: "blur(24px)", pointerEvents: "none",
        }} />
        <div className="relative flex items-center gap-4">
          <div className="w-12 h-12 rounded-2xl flex items-center justify-center shrink-0"
            style={{ background: `${PURPLE}22`, border: `1.5px solid ${PURPLE}45`, boxShadow: `0 0 24px ${PURPLE}28` }}>
            <Bot className="w-6 h-6" style={{ color: "#c4b5fd" }} />
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-0.5">
              <h1 className="text-lg font-extrabold" style={{ color: TEXT, fontFamily: "Vazirmatn,sans-serif" }}>
                یارمەتیدەری LinQi
              </h1>
              <span className="text-[9px] font-extrabold px-2 py-0.5 rounded-full"
                style={{ background: `${PURPLE}20`, color: "#c4b5fd", border: `1px solid ${PURPLE}45` }}>
                AI · B2B
              </span>
            </div>
            <p className="text-[11px]" style={{ color: "rgba(255,255,255,0.45)", fontFamily: "Vazirmatn,sans-serif" }}>
              کۆپایلۆتی کارەبایی — پرسیار، شیکاری، پێشنیاز بە زمانی کوردی
            </p>
          </div>
          {/* Live indicator */}
          <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl shrink-0"
            style={{ background: "rgba(16,185,129,0.10)", border: "1px solid rgba(16,185,129,0.2)" }}>
            <span className="relative flex h-2 w-2">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full opacity-60"
                style={{ background: GREEN }} />
              <span className="relative inline-flex h-2 w-2 rounded-full" style={{ background: GREEN }} />
            </span>
            <span className="text-[10px] font-bold" style={{ color: "#34d399" }}>ئۆنلاینە</span>
          </div>
        </div>
      </motion.div>

      {/* ── Quick-action grid ── */}
      <div>
        <p className="text-[10px] font-bold mb-3 flex items-center gap-1.5"
          style={{ color: MUTED, fontFamily: "Vazirmatn,sans-serif" }}>
          <Zap className="w-3 h-3" />
          دوگمەکانی خێرا — کلیک بکە بۆ دەستپێکردن
        </p>
        <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-6 gap-3">
          {QUICK_ACTIONS.map((qa, i) => {
            const Icon = qa.icon;
            return (
              <motion.button
                key={qa.label}
                initial={{ opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.05 }}
                onClick={() => sendMessage(qa.prompt)}
                disabled={loading}
                className="flex flex-col items-start gap-2 p-3.5 rounded-2xl text-start transition-all duration-200 group"
                style={glass({
                  cursor: loading ? "not-allowed" : "pointer",
                  opacity: loading ? 0.5 : 1,
                })}
                onMouseEnter={e => {
                  if (!loading) {
                    (e.currentTarget as HTMLElement).style.background = "rgba(255,255,255,0.055)";
                    (e.currentTarget as HTMLElement).style.borderColor = `${qa.color}35`;
                    (e.currentTarget as HTMLElement).style.transform = "translateY(-2px)";
                    (e.currentTarget as HTMLElement).style.boxShadow = `0 8px 24px rgba(0,0,0,0.3), 0 0 0 1px ${qa.color}22`;
                  }
                }}
                onMouseLeave={e => {
                  (e.currentTarget as HTMLElement).style.background = "rgba(255,255,255,0.03)";
                  (e.currentTarget as HTMLElement).style.borderColor = "rgba(255,255,255,0.06)";
                  (e.currentTarget as HTMLElement).style.transform = "translateY(0)";
                  (e.currentTarget as HTMLElement).style.boxShadow = "none";
                }}
              >
                <div className="w-8 h-8 rounded-xl flex items-center justify-center"
                  style={{ background: `${qa.color}16`, border: `1.5px solid ${qa.color}32` }}>
                  <Icon className="w-4 h-4" style={{ color: qa.color }} />
                </div>
                <div>
                  <p className="text-[11px] font-extrabold leading-snug" style={{ color: TEXT, fontFamily: "Vazirmatn,sans-serif" }}>
                    {qa.label}
                  </p>
                  <p className="text-[9px] mt-0.5" style={{ color: MUTED, fontFamily: "Vazirmatn,sans-serif" }}>
                    {qa.sub}
                  </p>
                </div>
                <ChevronRight className="w-3 h-3 mt-auto self-end" style={{ color: qa.color, opacity: 0.6 }} />
              </motion.button>
            );
          })}
        </div>
      </div>

      {/* ── Chat window ── */}
      <motion.div
        initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.25 }}
        className="flex flex-col"
        style={{ ...glass(), flex: 1, minHeight: "360px", overflow: "hidden" }}>

        {/* Chat header */}
        <div className="flex items-center justify-between px-5 py-3.5"
          style={{ borderBottom: "1px solid rgba(255,255,255,0.06)" }}>
          <div className="flex items-center gap-2">
            <Sparkles className="w-4 h-4" style={{ color: PURPLE }} />
            <span className="text-[12px] font-bold" style={{ color: TEXT, fontFamily: "Vazirmatn,sans-serif" }}>
              کۆنسۆڵی LinQi AI
            </span>
          </div>
          <button
            onClick={() => setMessages([{ id: "welcome-reset", role: "assistant", text: AI_RESPONSES.default[0], ts: new Date() }])}
            className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-bold transition-all"
            style={{ background: "rgba(255,255,255,0.04)", color: MUTED, border: "1px solid rgba(255,255,255,0.06)" }}
            onMouseEnter={e => { (e.currentTarget as HTMLElement).style.borderColor = `${PURPLE}35`; (e.currentTarget as HTMLElement).style.color = "#c4b5fd"; }}
            onMouseLeave={e => { (e.currentTarget as HTMLElement).style.borderColor = "rgba(255,255,255,0.06)"; (e.currentTarget as HTMLElement).style.color = MUTED; }}>
            <RefreshCw className="w-3 h-3" />
            نوێکردنەوە
          </button>
        </div>

        {/* Messages scroll area */}
        <div className="flex-1 overflow-y-auto px-5 py-4 space-y-4" style={{ maxHeight: "420px" }}>
          <AnimatePresence initial={false}>
            {messages.map(msg => (
              <motion.div
                key={msg.id}
                initial={{ opacity: 0, y: 10, scale: 0.97 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                transition={{ duration: 0.2 }}
                className={`flex gap-3 ${msg.role === "user" ? "flex-row-reverse" : "flex-row"}`}
              >
                {/* Avatar */}
                <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0 mt-0.5"
                  style={msg.role === "assistant"
                    ? { background: `${PURPLE}20`, border: `1.5px solid ${PURPLE}40` }
                    : { background: "rgba(6,182,212,0.18)", border: `1.5px solid ${CYAN}40` }}>
                  {msg.role === "assistant"
                    ? <Bot className="w-4 h-4" style={{ color: "#c4b5fd" }} />
                    : <Users className="w-4 h-4" style={{ color: CYAN }} />}
                </div>

                {/* Bubble */}
                <div className="flex-1 max-w-[82%]">
                  <div
                    className="rounded-2xl px-4 py-3"
                    style={msg.role === "assistant"
                      ? {
                          background: "rgba(139,92,246,0.08)",
                          border:     `1px solid ${PURPLE}22`,
                          borderStartStartRadius: "4px",
                          color: SUB,
                        }
                      : {
                          background: "rgba(6,182,212,0.10)",
                          border:     `1px solid ${CYAN}22`,
                          borderStartEndRadius: "4px",
                          color: TEXT,
                          textAlign: "end" as const,
                        }}>
                    {msg.typing
                      ? <TypingDots />
                      : msg.role === "assistant"
                        ? <MsgText text={msg.text} />
                        : <p style={{ fontFamily: "Vazirmatn,sans-serif", fontSize: "13px" }}>{msg.text}</p>
                    }
                  </div>
                  <p className={`text-[9px] mt-1 px-1 ${msg.role === "user" ? "text-end" : ""}`}
                    style={{ color: "rgba(100,116,139,0.7)" }}>
                    {fmtTime(msg.ts)}
                  </p>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
          <div ref={bottomRef} />
        </div>

        {/* ── Input bar ── */}
        <div className="px-4 pb-4 pt-3" style={{ borderTop: "1px solid rgba(255,255,255,0.05)" }}>
          <div className="flex items-end gap-3 rounded-2xl p-2"
            style={{
              background: "rgba(255,255,255,0.04)",
              border:     `1px solid ${loading ? `${PURPLE}35` : "rgba(255,255,255,0.08)"}`,
              transition: "border-color 0.2s",
              boxShadow:  loading ? `0 0 0 3px ${PURPLE}14` : "none",
            }}>
            <textarea
              ref={inputRef}
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={handleKey}
              disabled={loading}
              rows={1}
              placeholder="لێرە پرسیارەکەت یان فەرمانەکەت بنووسە…"
              className="flex-1 bg-transparent outline-none resize-none text-[13px] leading-relaxed"
              style={{
                color:       TEXT,
                fontFamily:  "Vazirmatn,sans-serif",
                maxHeight:   "120px",
                minHeight:   "24px",
                paddingInlineStart: "6px",
              }}
              onInput={e => {
                const el = e.currentTarget;
                el.style.height = "auto";
                el.style.height = Math.min(el.scrollHeight, 120) + "px";
              }}
            />
            <button
              onClick={() => sendMessage(input)}
              disabled={loading || !input.trim()}
              className="w-9 h-9 rounded-xl flex items-center justify-center shrink-0 transition-all"
              style={input.trim() && !loading
                ? { background: `linear-gradient(135deg, ${PURPLE}, ${BLUE})`, boxShadow: `0 4px 16px ${PURPLE}40`, cursor: "pointer" }
                : { background: "rgba(255,255,255,0.06)", cursor: "not-allowed", opacity: 0.45 }}>
              {loading
                ? <motion.div animate={{ rotate: 360 }} transition={{ duration: 1, repeat: Infinity, ease: "linear" }}>
                    <RefreshCw className="w-4 h-4" style={{ color: "#c4b5fd" }} />
                  </motion.div>
                : <Send className="w-4 h-4" style={{ color: input.trim() ? TEXT : MUTED }} />
              }
            </button>
          </div>
          <p className="text-[9px] mt-1.5 text-center" style={{ color: "rgba(100,116,139,0.5)", fontFamily: "Vazirmatn,sans-serif" }}>
            Enter بکە بۆ ناردن · Shift+Enter بۆ هێڵی نوێ · ئەمە سیمیولەیشنی AI‌یە
          </p>
        </div>
      </motion.div>

    </div>
  );
}

