import { useState, useRef, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Bot, Lightbulb, TrendingUp, FileText, Zap, Brain,
  Send, Sparkles, BarChart3, Package, Users, RefreshCw,
  ChevronRight,
} from "lucide-react";

/* ─────────────────────────────────────────────────────────────────── */
/*  DESIGN TOKENS                                                       */
/* ─────────────────────────────────────────────────────────────────── */
const PURPLE = "#8b5cf6";
const CYAN   = "#06b6d4";
const GREEN  = "#10b981";
const BLUE   = "#3b82f6";
const TEXT   = "#f1f5f9";
const MUTED  = "#64748b";
const SUB    = "#94a3b8";

const glass = (extra?: React.CSSProperties): React.CSSProperties => ({
  background:           "rgba(255,255,255,0.03)",
  backdropFilter:       "blur(24px)",
  WebkitBackdropFilter: "blur(24px)",
  border:               "1px solid rgba(255,255,255,0.06)",
  borderRadius:         "16px",
  ...extra,
});

/* ─────────────────────────────────────────────────────────────────── */
/*  RESPONSE BANK — conversational, varied, no bullet dumps            */
/* ─────────────────────────────────────────────────────────────────── */
const RESPONSES: Record<string, string[]> = {
  sales: [
    `فرۆشی مانگی حوزەیران بە ئێستاکەیدا زۆر باشە. کۆی فرۆشەکان گەیشتووەتە ٤٨.٧ ملیۆن د.ع — ئەمەش ١٢.٤٪ زیاترە لە مانگی پێشووتان.\n\nباشترین بەرهەمی فرۆشراو ئەم هەفتەیە روونی زەیتوون بووە، پاشانیش ماکارۆنی ئیتالی و شەکری سپی. پێشبینیم ئەوەیە کە ئەگەر ئەنباری ئان بەرهەمانە پر بمێنێت، مانگی داهاتوو دەتوانیت ١٠–١٤٪ زیاتر بفرۆشیت.\n\nدەتەوێت شیکارییەکی قووڵتری بۆ بەرهەمێکی دیاری بکەم؟`,
    `دیتای فرۆشی ئەمڕۆیان پیشانم دا: ٦ مامەڵەی نوێ تۆمار کراوە تا ئێستا لە ئەم هەفتەیەدا، کۆی ئەوانەش ١٢.٣ ملیۆن د.ع دەبێت.\n\nئەم مانگە ئاوێنەیەکی باشی کار نیشان دەدات. ئایا دەتەوێت بزانیت کام کڕیارت زیاتر فرۆش لێکردووە؟`,
  ],
  inventory: [
    `ئەنبارەکانت لەگەڵ دووی دەبێت بگرمەوە. ٣ بەرهەمت هەیە کە زۆر نزیک دایە بۆ ئاستی تەخشیر:\n\nروونی زەیتوون ٣٢ دەبەی مایەوە — ئاستی ئەمنیت ٥٠ دەبەیە. دانەی قاوە ١٨ کیلۆی مایەوە، پێویستی فوری هەیە. سابوونی ماشینیش ٦٤ کارتۆن — لە ئاستی هۆشداری دایە.\n\nپیشنیارم ئەوەیە کە ئیمڕۆ داواکاری B2B بنێریت بۆ شیرکەتی ئەڵفا. دەتەوێت ئەمەی بۆت دروست بکەم؟`,
    `ستۆکی ئەنبارت بە گشتی چاکە، بەڵام دووی هەیە کە دەبێت ئێستا چارەسەریان بکەیت. روونی زەیتوون و دانەی قاوە هەر دوووکیان لە ئاستی کریتیکالدان. داواکاری نوێ پێویستە، وا نەبێت ملیۆنەکان لە فرۆش دەچوو.\n\nئایا دەتەوێت خودکار داواکاری بنێرم بۆ دابینکەرانت؟`,
