/* Rotate through variants so repeat clicks feel fresh */
const counters: Record<string, number> = {};
function pick(key: string): string {
  const pool = RESPONSES[key] ?? RESPONSES.fallback;
  const idx  = (counters[key] ?? 0) % pool.length;
  counters[key] = idx + 1;
  return pool[idx];
}

function route(input: string): string {
  const q = input;
  if (q.includes("سڵاو") || q.includes("خوشحال") || q.includes("باشی"))
    return "سڵاو! خۆشحاڵم کە دەبینمت. ئەمڕۆ چۆن دەتوانم یارمەتیت بدەم؟";
  if (q.includes("فرۆش") || q.includes("داهات") || q.includes("مامەڵە") || q.includes("sales") || q.includes("شیکاری فرۆش"))
    return pick("sales");
  if (q.includes("ئەنبار") || q.includes("ستۆک") || q.includes("inventory") || q.includes("کاڵا") || q.includes("بەرهەم"))
    return pick("inventory");
  if (q.includes("ستراتیژ") || q.includes("پێشنیار") || q.includes("strategy") || q.includes("بەهێزکردن") || q.includes("گەشەکردن"))
    return pick("strategy");
  if (q.includes("ڕاپۆرت") || q.includes("report") || q.includes("دروستکردن"))
    return pick("report");
  if (q.includes("بازاڕ") || q.includes("market") || q.includes("فرصەت") || q.includes("تووێژ"))
    return pick("market");
  if (q.includes("مێژوو") || q.includes("تایبەتی") || q.includes("فێربوون") || q.includes("کارەکانم"))
    return pick("personal");
  return pick("fallback");
}

