      ))}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────── */
/*  TYPEWRITER TEXT — reveals one char at a time                       */
/* ─────────────────────────────────────────────────────────────────── */
function TypewriterText({ fullText, onDone }: { fullText: string; onDone: () => void }) {
  const [displayed, setDisplayed] = useState("");
  const doneRef = useRef(false);

  useEffect(() => {
    doneRef.current = false;
    setDisplayed("");
    let i = 0;
    /* Speed: ~18 ms/char feels like a fast real AI stream */
    const id = setInterval(() => {
      if (i >= fullText.length) {
        clearInterval(id);
        if (!doneRef.current) { doneRef.current = true; onDone(); }
        return;
      }
      setDisplayed(fullText.slice(0, i + 1));
      i++;
    }, 18);
    return () => clearInterval(id);
  }, [fullText]); // eslint-disable-line react-hooks/exhaustive-deps

  return <RichText text={displayed} streaming />;
}

/* ─────────────────────────────────────────────────────────────────── */
/*  RICH TEXT — bold (**…**) + newlines, cursor blink when streaming  */
/* ─────────────────────────────────────────────────────────────────── */
function RichText({ text, streaming }: { text: string; streaming?: boolean }) {
  const lines = text.split("\n");
  return (
    <div style={{ fontFamily: "Vazirmatn,sans-serif", lineHeight: "1.75", fontSize: "13px", color: SUB }}>
      {lines.map((line, li) => {
        const parts = line.split(/\*\*(.*?)\*\*/g);
        return (
          <p key={li} style={{ marginBottom: li < lines.length - 1 ? "4px" : 0 }}>
            {parts.map((part, pi) =>
              pi % 2 === 1
                ? <strong key={pi} style={{ color: TEXT, fontWeight: 800 }}>{part}</strong>
                : <span key={pi}>{part}</span>
            )}
            {/* blinking cursor on the last visible line */}
            {streaming && li === lines.length - 1 && (
              <motion.span
                animate={{ opacity: [1, 0, 1] }}
                transition={{ duration: 0.7, repeat: Infinity }}
                style={{ display: "inline-block", width: "2px", height: "14px",
                  background: PURPLE, marginInlineStart: "2px", verticalAlign: "text-bottom",
                  borderRadius: "1px" }}
              />
            )}
          </p>
        );
      })}
    </div>
  );
}

